using System.Collections.Generic;
using System.IO;
using NUnit.Framework;
using OpenFifa.Core;

namespace OpenFifa.Tests.Editor
{
    /// <summary>
    /// Kit clash resolution by broadcast contrast (<see cref="KitBroadcastContrast"/>,
    /// <see cref="KitLibraryLogic.ResolveMatchKitsContrasting"/>), on hand-made kits and on every pairing of the shipped
    /// Premier League pack (kits generated by <see cref="ClubKitFactory"/> from each club's colours, as in a match).
    /// </summary>
    [TestFixture]
    [Category("Kits")]
    [Category("FID_KITS")]
    public class KitBroadcastContrastTests
    {
        private static IReadOnlyList<RosterClub> _clubs;

        private static IReadOnlyList<RosterClub> Clubs
        {
            get
            {
                if (_clubs != null) return _clubs;
                var r = RosterLoader.Load(File.ReadAllText(RosterTestData.PremierLeaguePath), "premier_league.roster.json");
                Assert.IsTrue(r.Success, r.Describe());
                _clubs = r.League.Clubs;
                return _clubs;
            }
        }

        private static RosterClub Club(string shortName)
        {
            foreach (var c in Clubs) if (c.ShortName == shortName) return c;
            Assert.Fail("no club " + shortName);
            return null;
        }

        private static KitLibraryLogic Library(RosterClub home, RosterClub away)
        {
            var logic = new KitLibraryLogic(ClubKitFactory.Build(home));
            logic.Merge(ClubKitFactory.Build(away));
            return logic;
        }

        private static MatchKitSelection Resolve(string home, string away)
        {
            var h = Club(home);
            var a = Club(away);
            return Library(h, a).ResolveMatchKitsContrasting(h.Id, a.Id);
        }

        private static KitDefinitionData Plain(string shirt, string shorts) =>
            new KitDefinitionData { Id = shirt + shorts, TeamId = "t", Variant = "Home", PrimaryColor = shirt, ShortsColor = shorts };

        [TestCase(50f, 2.6772f, -79.7751f, 50f, 0f, -82.7485f, 2.0425f)]
        [TestCase(50f, -1.3802f, -84.2814f, 50f, 0f, -82.7485f, 1.0000f)]
        [TestCase(50f, 2.5f, 0f, 50f, 0f, -2.5f, 4.3065f)]
        [TestCase(60.2574f, -34.0099f, 36.2677f, 60.4626f, -34.1751f, 39.4387f, 1.2644f)]
        [TestCase(22.7233f, 20.0904f, -46.694f, 23.0331f, 14.973f, -42.5619f, 2.0373f)]
        public void DeltaE2000_SharmaReferencePairs_MatchPublishedValues(float l1, float a1, float b1, float l2, float a2, float b2,
            float expected)
        {
            float de = KitBroadcastContrast.DeltaE2000(new KitBroadcastContrast.Lab(l1, a1, b1), new KitBroadcastContrast.Lab(l2, a2, b2));
            Assert.AreEqual(expected, de, 1e-3f);
        }

        [Test]
        public void ToLab_WhiteAndBlack_AreTheEndsOfTheLightnessScale()
        {
            var white = KitBroadcastContrast.ToLab(SimpleColor.White);
            var black = KitBroadcastContrast.ToLab(SimpleColor.Black);
            Assert.AreEqual(100f, white.L, 0.05f);
            Assert.AreEqual(0f, white.A, 0.05f);
            Assert.AreEqual(0f, white.B, 0.05f);
            Assert.AreEqual(0f, black.L, 0.05f);
        }

        [Test]
        public void Contrast_SkyBlueVersusWhite_ClashesThoughRgbDistanceSaysDifferent()
        {
            var sky = Plain("#7DB3DD", "#FFFFFF");
            var white = Plain("#EDEBE3", "#EDEBE3");
            Assert.Greater(JerseyComparer.ColorDistance(KitColorUtility.ParseOrDefault(sky.PrimaryColor, SimpleColor.Black),
                KitColorUtility.ParseOrDefault(white.PrimaryColor, SimpleColor.Black)), JerseyComparer.DefaultClashThreshold,
                "the old RGB rule saw these as different");
            Assert.IsTrue(KitBroadcastContrast.Clashes(sky, white), $"contrast {KitBroadcastContrast.Contrast(sky, white):F1}");
        }

        [Test]
        public void Contrast_RedVersusSkyBlue_IsClear()
        {
            var red = Plain("#EF4347", "#FFFFFF");
            var sky = Plain("#7DB3DD", "#FFFFFF");
            Assert.IsFalse(KitBroadcastContrast.Clashes(red, sky), $"contrast {KitBroadcastContrast.Contrast(red, sky):F1}");
        }

        [Test]
        public void Contrast_NavyVersusMaroon_ClashesBecauseDarkHuesFadeFromTheGantry()
        {
            var navy = Plain("#1B3F8F", "#1B3F8F");
            var maroon = Plain("#7A2639", "#7A2639");
            Assert.IsTrue(KitBroadcastContrast.Clashes(navy, maroon), $"contrast {KitBroadcastContrast.Contrast(navy, maroon):F1}");
        }

        [Test]
        public void Contrast_IsSymmetricAndZeroForTheSameKit()
        {
            var a = Plain("#C8102E", "#FFFFFF");
            var b = Plain("#0057B8", "#0057B8");
            Assert.AreEqual(KitBroadcastContrast.Contrast(a, b), KitBroadcastContrast.Contrast(b, a), 1e-3f);
            Assert.AreEqual(0f, KitBroadcastContrast.Contrast(a, a), 1e-3f);
        }

        [Test]
        public void ShirtColour_StripedShirt_BlendsTowardTheSecondary()
        {
            var striped = new KitDefinitionData { PrimaryColor = "#FFFFFF", SecondaryColor = "#000000", Pattern = "Stripes" };
            var solid = new KitDefinitionData { PrimaryColor = "#FFFFFF", SecondaryColor = "#000000", Pattern = "Solid" };
            Assert.Less(KitBroadcastContrast.ShirtColour(striped).R, 0.7f);
            Assert.AreEqual(1f, KitBroadcastContrast.ShirtColour(solid).R, 1e-4f);
        }

        [Test]
        public void PremierLeague_ManCityHomeVsArsenal_ArsenalKeepsItsRedHomeKit()
        {
            // The capture glitch: the old luminance-gap rule moved Arsenal into an off-white kit against sky blue.
            var sel = Resolve("MCI", "ARS");
            Assert.AreEqual(KitVariant.Home, sel.AwayVariant, sel.AwayKit.Id);
            Assert.IsFalse(sel.ClashUnresolved);
            Assert.GreaterOrEqual(sel.Contrast, KitBroadcastContrast.MinContrast);
            var arsenalLight = Library(Club("MCI"), Club("ARS")).GetKit(Club("ARS").Id, KitVariant.Third);
            Assert.IsTrue(KitBroadcastContrast.Clashes(sel.HomeKit, arsenalLight), "Arsenal's off-white third kit v sky blue must count as a clash");
        }

        [TestCase("TOT", "FUL")] // both white at home
        [TestCase("FUL", "TOT")]
        [TestCase("CHE", "EVE")] // royal blues
        [TestCase("EVE", "CHE")]
        [TestCase("BHA", "CHE")]
        [TestCase("CRY", "CHE")]
        [TestCase("IPS", "BHA")]
        [TestCase("LIV", "MUN")] // reds
        [TestCase("MUN", "NFO")]
        [TestCase("NFO", "ARS")]
        [TestCase("SUN", "BRE")]
        [TestCase("BOU", "SUN")]
        [TestCase("MCI", "COV")] // sky blues
        [TestCase("COV", "MCI")]
        [TestCase("LEE", "MCI")] // white v sky blue
        [TestCase("MCI", "LEE")]
        [TestCase("TOT", "AVL")]
        public void PremierLeague_KnownClosePairs_AwaySideChangesKit(string home, string away)
        {
            var h = Club(home);
            var a = Club(away);
            var logic = Library(h, a);
            var homeKit = logic.GetKit(h.Id, KitVariant.Home);
            var awayHome = logic.GetKit(a.Id, KitVariant.Home);
            Assert.IsTrue(KitBroadcastContrast.Clashes(homeKit, awayHome),
                $"{home} v {away} home kits: contrast {KitBroadcastContrast.Contrast(homeKit, awayHome):F1}");
            var sel = logic.ResolveMatchKitsContrasting(h.Id, a.Id);
            Assert.AreNotEqual(KitVariant.Home, sel.AwayVariant);
            Assert.Greater(sel.Contrast, KitBroadcastContrast.Contrast(homeKit, awayHome) + 5f);
        }

        [Test]
        public void PremierLeague_EveryPairing_PicksTheFirstClearKitOrElseTheMostContrasting()
        {
            int unresolved = 0;
            var problems = new List<string>();
            foreach (var h in Clubs)
                foreach (var a in Clubs)
                {
                    if (h == a) continue;
                    var logic = Library(h, a);
                    var sel = logic.ResolveMatchKitsContrasting(h.Id, a.Id);
                    Assert.AreEqual(KitVariant.Home, KitDefinitionConverter.GetVariant(sel.HomeKit));
                    float best = float.NegativeInfinity;
                    KitVariant firstClear = (KitVariant)(-1);
                    foreach (var v in new[] { KitVariant.Home, KitVariant.Away, KitVariant.Third })
                    {
                        float c = KitBroadcastContrast.Contrast(sel.HomeKit, logic.GetKit(a.Id, v));
                        if (c > best) best = c;
                        if ((int)firstClear < 0 && c >= KitBroadcastContrast.MinContrast) firstClear = v;
                    }
                    if ((int)firstClear >= 0)
                    {
                        if (sel.AwayVariant != firstClear) problems.Add($"{h.ShortName} v {a.ShortName}: {sel.AwayVariant}, expected {firstClear}");
                    }
                    else
                    {
                        unresolved++;
                        Assert.IsTrue(sel.ClashUnresolved, h.ShortName + " v " + a.ShortName);
                        Assert.AreEqual(best, sel.Contrast, 1e-3f, h.ShortName + " v " + a.ShortName);
                    }
                }
            CollectionAssert.IsEmpty(problems, string.Join("; ", problems));
            // 380 pairings; two have no kit above the threshold (LEE v NFO and NFO v ARS, both about 21).
            Assert.LessOrEqual(unresolved, 2);
        }

        [Test]
        public void ResolveMatchKitsContrasting_NoAwayKits_KeepsTheBasicSelection()
        {
            var logic = new KitLibraryLogic(ClubKitFactory.Build("a", "A", "AAA", "#1B3F8F", "#F2C230", "#FFFFFF"));
            var sel = logic.ResolveMatchKitsContrasting("a", "missing");
            Assert.IsNotNull(sel.HomeKit);
            Assert.IsNull(sel.AwayKit);
        }
    }
}
